From d8e0c92acaa7659d9387024c6cbbb2b8297cfcf7 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:28:36 +0100
Subject: [PATCH] components/calendar: Change the month with every wheel step

The wheel handler only accepted mice, but QtWayland reports all pointers
as touchpads, so a wheel step fell through to the swipe view and snapped
back. Accept touchpads too, with a longer step for touchpad swipes.

BUG: 479972
---
 components/calendar/qml/MonthView.qml | 17 ++++++++++++-----
 1 file changed, 12 insertions(+), 5 deletions(-)

diff --git a/components/calendar/qml/MonthView.qml b/components/calendar/qml/MonthView.qml
index 619852a770..878f7a2b0a 100644
--- a/components/calendar/qml/MonthView.qml
+++ b/components/calendar/qml/MonthView.qml
@@ -312,18 +312,25 @@ Item {
         }

         WheelHandler {
-            acceptedDevices: PointerDevice.Mouse
+            // QtWayland reports every wheel device as a touchpad
+            acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
             orientation: Qt.Vertical
             parent: swipeView.currentItem
             onWheel: wheel => {
+                if (wheel.phase === Qt.ScrollBegin || wheel.phase === Qt.ScrollEnd) {
+                    rotation = 0;
+                    return;
+                }
                 // magic number 15 for common "one scroll"
                 // See https://doc.qt.io/qt-6/qml-qtquick-wheelhandler.html#rotation-prop
-                while (rotation >= 15) {
-                    rotation -= 15;
+                // Touchpad gestures need a longer swipe so a light touch doesn't skip months
+                const step = wheel.phase === Qt.NoScrollPhase ? 15 : 90;
+                while (rotation >= step) {
+                    rotation -= step;
                     root.previousView();
                 }
-                while (rotation <= -15) {
-                    rotation += 15;
+                while (rotation <= -step) {
+                    rotation += step;
                     root.nextView();
                 }
             }
